begin;
do $$ declare owner uuid:=gen_random_uuid(); a uuid;i uuid;r uuid;p uuid:=gen_random_uuid();q uuid:=gen_random_uuid();j jsonb;v integer;n integer;path text;
begin
 insert into auth.users(id,email,email_confirmed_at,is_anonymous) values(owner,'automation-probe@example.invalid',now(),false);
 insert into public.analyses(owner_id,business_type,business_category,status) values(owner,'coffee-shop','coffee-shop','free_ready') returning id into a;
 insert into public.analysis_inputs(analysis_id,version,user_supplied) values(a,1,'{}') returning id into i;
 insert into public.reports(analysis_id,input_id,version,schema_version,tier,status,free_projection) values(a,i,1,2,'free','ready','{}') returning id into r;
 insert into public.sale_policies(version,approved,classification,confirmation_channel,snapshot) values('automation-probe',true,'digital_content','synthetic-only','{"sellerName":"Synthetic only","sellerAddress":"Synthetic only","privacyContact":"test@example.invalid","supportContact":"test@example.invalid","taxTreatment":"Synthetic only","termsText":"Synthetic frozen contract only.","privacyText":"Synthetic privacy information only.","retentionText":"Synthetic retention information only."}');
 perform public.prepare_sitefit_payment(owner,r,p,'price_automation',jsonb_build_object('mode','payment','customer_email','automation-probe@example.invalid','metadata',jsonb_build_object('purchase_id',p,'analysis_id',a)),now()+interval '1 hour');
 perform public.record_sitefit_sale(owner,p,'automation-probe',jsonb_build_object('version','automation-probe','buyerKind','consumer','termsAccepted',true,'immediateRequested',true,'acknowledgement',true));
 if public.claim_sitefit_contract_email() is not null then raise exception 'disabled_mail_sent';end if;
 update public.contract_email_control set enabled=true;
 if public.claim_sitefit_contract_email() is not null then raise exception 'unpaid_mail_sent';end if;
 perform public.bind_sitefit_checkout(p,'cs_test_automation');select revision into v from public.payments where id=p;
 perform public.confirm_sitefit_payment(p,'evt_automation','checkout.session.completed',v,'cs_test_automation','pi_automation','paid','none');
 j:=public.claim_sitefit_contract_email();if j is null or j->>'paymentId'<>p::text then raise exception 'paid_mail_not_claimed';end if;
 if public.claim_sitefit_contract_email() is not null then raise exception 'duplicate_email_claim';end if;
 if public.sitefit_supply_permitted(p) then raise exception 'preparation_was_delivery';end if;
 path:='contracts/'||p::text||'/'||repeat('b',64)||'/confirmation.pdf';
 begin perform public.intent_sitefit_contract_email(p,(j->>'token')::uuid,path,repeat('a',64),repeat('b',64));raise exception 'missing_document_accepted';exception when others then if sqlerrm='missing_document_accepted' then raise;end if;end;
 insert into storage.objects(bucket_id,name) values('sitefit-private-documents',path);
 perform public.intent_sitefit_contract_email(p,(j->>'token')::uuid,path,repeat('a',64),repeat('b',64));
 if public.sitefit_supply_permitted(p) then raise exception 'intent_was_delivery';end if;
 perform public.finish_sitefit_contract_email(p,(j->>'token')::uuid,'sent','123456789');
 perform public.finish_sitefit_contract_email(p,(j->>'token')::uuid,'sent','123456789');
 if not public.sitefit_supply_permitted(p) then raise exception 'accepted_pdf_not_admitted';end if;
 if exists(select 1 from public.sale_contracts where payment_id=p and confirmation_delivered_at is not null) then raise exception 'manual_delivery_fabricated';end if;
 if public.claim_sitefit_contract_email() is not null then raise exception 'sent_message_repeated';end if;
 begin perform public.finish_sitefit_contract_email(p,null,'uncertain',null);raise exception 'foreign_token_accepted';exception when others then if sqlerrm='foreign_token_accepted' then raise;end if;end;
 -- A second synthetic purchase uses its own graph to test unknown-outcome hold.
 insert into public.analyses(owner_id,business_type,business_category,status) values(owner,'restaurant','restaurant','free_ready') returning id into a;
 insert into public.analysis_inputs(analysis_id,version,user_supplied) values(a,1,'{}') returning id into i;
 insert into public.reports(analysis_id,input_id,version,schema_version,tier,status,free_projection) values(a,i,1,2,'free','ready','{}') returning id into r;
 perform public.prepare_sitefit_payment(owner,r,q,'price_automation',jsonb_build_object('mode','payment','customer_email','automation-probe@example.invalid','metadata',jsonb_build_object('purchase_id',q,'analysis_id',a)),now()+interval '1 hour');
 perform public.record_sitefit_sale(owner,q,'automation-probe',jsonb_build_object('version','automation-probe','buyerKind','consumer','termsAccepted',true,'immediateRequested',true,'acknowledgement',true));
 perform public.bind_sitefit_checkout(q,'cs_test_automation2');select revision into v from public.payments where id=q;
 perform public.confirm_sitefit_payment(q,'evt_automation2','checkout.session.completed',v,'cs_test_automation2','pi_automation2','paid','none');
 j:=public.claim_sitefit_contract_email();path:='contracts/'||q::text||'/'||repeat('c',64)||'/confirmation.pdf';insert into storage.objects(bucket_id,name) values('sitefit-private-documents',path);
 perform public.intent_sitefit_contract_email(q,(j->>'token')::uuid,path,repeat('a',64),repeat('c',64));
 perform public.finish_sitefit_contract_email(q,(j->>'token')::uuid,'uncertain',null);
 if public.claim_sitefit_contract_email() is not null or public.sitefit_supply_permitted(q) then raise exception 'uncertain_send_retried_or_supplied';end if;
 if has_table_privilege('authenticated','public.contract_email_jobs','select') or has_function_privilege('authenticated','public.claim_sitefit_contract_email()','execute') then raise exception 'email_private_boundary_open';end if;
end $$;
rollback;
